// Paginated fetch of Stripe checkout sessions for the last 30 days, with fee/refund and
// discount detail nested-expanded in the same call -- confirmed live 2026-08-12 both
// expands work together in one request, no extra per-row API call needed, unlike Paytrail
// (which has no list endpoint at all -- see payments-paytrail sync via the callback
// workflow instead). total_details.breakdown is needed for discounts specifically: the
// bare session.discounts field only gives an opaque promotion_code object ID, not the
// human-readable coupon code (see migration 009 comment). Uses this.helpers.httpRequest
// with a manually-provided auth header rather than an n8n credential -- Code nodes on this
// instance don't expose this.getCredentials(). Also confirmed live: this sandbox has no
// URLSearchParams global either (a real 'URLSearchParams is not defined' on first deploy),
// so the query string is built manually below instead.
const STRIPE_API_KEY = 'STRIPE_API_KEY_PLACEHOLDER';

const now = Math.floor(Date.now() / 1000);
const THIRTY_DAYS = 30 * 24 * 60 * 60;
const createdGte = now - THIRTY_DAYS;

let sessions = [];
let startingAfter = null;
let page = 0;
const MAX_PAGES = 50; // 100/page ceiling -- generous headroom over real ~30d volume

while (page < MAX_PAGES) {
  const params = [
    ['created[gte]', String(createdGte)],
    ['limit', '100'],
    ['expand[]', 'data.payment_intent.latest_charge.balance_transaction'],
    ['expand[]', 'data.total_details.breakdown'],
  ];
  if (startingAfter) params.push(['starting_after', startingAfter]);
  const qs = params.map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`).join('&');

  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.stripe.com/v1/checkout/sessions?${qs}`,
    headers: { Authorization: `Bearer ${STRIPE_API_KEY}` },
    json: true,
  });

  sessions = sessions.concat(resp.data || []);
  page += 1;
  if (!resp.has_more) break;
  startingAfter = resp.data[resp.data.length - 1].id;
}

return sessions.map((s) => ({ json: s }));

// GDPR: strips billing_details/customer_details/receipt_email/customer id entirely --
// only transactional fields needed for reconciliation/reporting cross the boundary into
// raw_payload or normalized columns. See migration 008 comment.
//
// Discounts (added migration 009, 2026-08-12, for the upsell_discount_used funnel stage):
// session.discounts only gives an opaque promotion_code object ID -- the human-readable
// coupon code lives on total_details.breakdown.discounts[].discount.coupon, matched
// positionally with session.discounts for the common single-discount case (multi-discount
// sessions are rare and the full detail is kept in the discounts JSONB column regardless).
function extractDiscounts(session) {
  const breakdown = (session.total_details && session.total_details.breakdown) || {};
  const entries = breakdown.discounts || [];
  const promoIds = (session.discounts || []).map((d) => d.promotion_code).filter(Boolean);
  return entries.map((entry, i) => {
    const coupon = (entry.discount && entry.discount.coupon) || {};
    return {
      coupon_id: coupon.id || null,
      coupon_name: coupon.name || null,
      percent_off: coupon.percent_off != null ? coupon.percent_off : null,
      amount_off_cents: coupon.amount_off != null ? coupon.amount_off : null,
      applied_cents: entry.amount != null ? entry.amount : null,
      promotion_code_id: promoIds[i] || null,
    };
  });
}

function clean(session) {
  const pi = session.payment_intent;
  const piObj = pi && typeof pi === 'object' ? pi : null;
  const charge = piObj ? piObj.latest_charge : null;
  const chargeObj = charge && typeof charge === 'object' ? charge : null;
  const bt = chargeObj ? chargeObj.balance_transaction : null;
  const btObj = bt && typeof bt === 'object' ? bt : null;

  return {
    id: session.id,
    payment_intent_id: piObj ? piObj.id : pi,
    charge_id: chargeObj ? chargeObj.id : charge,
    status: session.status,
    payment_status: session.payment_status,
    amount_total: session.amount_total,
    currency: session.currency,
    created: session.created,
    payment_method_types: session.payment_method_types,
    charge_created: chargeObj ? chargeObj.created : null,
    charge_paid: chargeObj ? chargeObj.paid : null,
    amount_refunded: chargeObj ? chargeObj.amount_refunded : null,
    payment_method_brand:
      chargeObj && chargeObj.payment_method_details
        ? (chargeObj.payment_method_details.card
            ? chargeObj.payment_method_details.card.brand
            : chargeObj.payment_method_details.type)
        : null,
    balance_transaction_fee: btObj ? btObj.fee : null,
    balance_transaction_net: btObj ? btObj.net : null,
    metadata: session.metadata || {},
    discounts: extractDiscounts(session),
  };
}

const results = [];
for (const item of $input.all()) {
  const s = item.json;
  const c = clean(s);
  const orderId = (s.metadata && s.metadata.order_id) || null;
  const primaryDiscount = c.discounts[0] || null;

  const row = {
    id: s.id,
    payment_intent_id: c.payment_intent_id,
    order_id: orderId,
    status: s.payment_status || s.status || null,
    amount_cents: s.amount_total != null ? s.amount_total : null,
    currency: s.currency || null,
    payment_method_type: c.payment_method_brand,
    created_at: s.created ? new Date(s.created * 1000).toISOString() : null,
    paid_at: c.charge_paid && c.charge_created ? new Date(c.charge_created * 1000).toISOString() : null,
    fee_cents: c.balance_transaction_fee,
    refund_amount_cents: c.amount_refunded,
    discount_coupon_code: primaryDiscount ? primaryDiscount.coupon_id : null,
    discount_percent_off: primaryDiscount ? primaryDiscount.percent_off : null,
    discount_amount_off_cents: primaryDiscount ? primaryDiscount.amount_off_cents : null,
    discount_applied_cents: primaryDiscount ? primaryDiscount.applied_cents : null,
    discounts: c.discounts,
    raw_payload: c,
    synced_at: new Date().toISOString(),
  };

  if (row.id) results.push({ json: row });
}

return results;
